    <script>document.addEventListener('DOMContentLoaded',function(){const products=@json($lookups['products']),colors=@json($lookups['colors']),oldProduct=@json(old('product_id')),oldColor=@json(old('color_id')),segment=document.getElementById('segment_id'),product=document.getElementById('product_id'),color=document.getElementById('color_id'),organization=document.getElementById('organization_id'),modal=document.getElementById('organization-modal'),form=document.getElementById('organization-form'),error=document.getElementById('organization-error');const select2=window.jQuery&&window.jQuery.fn&&window.jQuery.fn.select2;if(select2)window.jQuery('.js-lead-select').select2({width:'100%'});function refresh(select){if(select2)window.jQuery(select).trigger('change.select2')}function setOptions(select,placeholder,items,selected){select.replaceChildren(new Option(placeholder,''));items.forEach(item=>select.add(new Option(item.name,item.id,false,String(item.id)===String(selected))));select.disabled=!items.length;refresh(select)}function loadProducts(selected=''){const items=segment.value?products.filter(item=>String(item.segment_id)===String(segment.value)):[];setOptions(product,segment.value?'Select product':'Select segment first',items,selected);loadColors('')}function loadColors(selected=''){const items=product.value?colors:[];setOptions(color,product.value?'Select color':'Select product first',items,selected)}segment.addEventListener('change',()=>loadProducts(''));product.addEventListener('change',()=>loadColors(''));if(segment.value)loadProducts(oldProduct);if(product.value)loadColors(oldColor);function closeModal(){modal.classList.add('hidden');modal.classList.remove('flex');form.reset();error.classList.add('hidden')}document.getElementById('add-organization-button').addEventListener('click',()=>{modal.classList.remove('hidden');modal.classList.add('flex');form.querySelector('[name=name]').focus()});document.getElementById('close-organization-modal').addEventListener('click',closeModal);document.getElementById('cancel-organization').addEventListener('click',closeModal);form.addEventListener('submit',async event=>{event.preventDefault();error.classList.add('hidden');const response=await fetch(@json(route('leads.organizations.store')),{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name=csrf-token]').content},body:JSON.stringify(Object.fromEntries(new FormData(form)))});const result=await response.json();if(!response.ok){error.textContent=result.message||Object.values(result.errors||{}).flat().join(' ');error.classList.remove('hidden');return}organization.add(new Option(result.text,result.id,true,true));organization.value=String(result.id);refresh(organization);closeModal()})})</script>
    <script>document.addEventListener('DOMContentLoaded',function(){const phone=document.getElementById('lead-phone'),warning=document.getElementById('lead-phone-warning'),save=document.getElementById('lead-save-button');let lastAlert='';function clearWarning(){warning.textContent='';warning.classList.add('hidden');save.disabled=false}async function checkPhone(){const value=phone.value.trim();clearWarning();if(!value)return;const response=await fetch(@json(route('leads.check-contact'))+'?phone='+encodeURIComponent(value),{headers:{Accept:'application/json'}});const result=await response.json();if(value!==phone.value.trim()||!result.exists)return;warning.textContent=result.message;warning.classList.remove('hidden');save.disabled=true;if(lastAlert!==result.message){window.alert(result.message);lastAlert=result.message}}phone.addEventListener('input',clearWarning);phone.addEventListener('change',checkPhone);phone.addEventListener('blur',checkPhone);if(phone.value.trim())checkPhone()})</script>
